import{_ as e,o as i,c as l,a2 as t}from"./chunks/framework.BXA5Pi9t.js";const _=JSON.parse('{"title":"Ceph Crimson/SeaStore Meeting 2023-01-11","description":"","frontmatter":{"title":"Ceph Crimson/SeaStore Meeting 2023-01-11","date":"2023-01-11T00:00:00.000Z","updated":"2023-01-13T00:00:00.000Z","tags":["Ceph","分布式存储","Crimson","SeaStore","构建问题"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2023/Ceph_Crimson_SeaStore_Meeting_2023-01-11.md","filePath":"posts/2023/Ceph_Crimson_SeaStore_Meeting_2023-01-11.md","lastUpdated":1780460162000}'),r={name:"posts/2023/Ceph_Crimson_SeaStore_Meeting_2023-01-11.md"};function o(n,a,s,h,d,u){return i(),l("div",null,[...a[0]||(a[0]=[t('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="会议时间-2023-01-11" tabindex="-1">会议时间：2023-01-11 <a class="header-anchor" href="#会议时间-2023-01-11" aria-label="Permalink to &quot;会议时间：2023-01-11&quot;">​</a></h4><h4 id="参会人员-具体人员名单" tabindex="-1">参会人员：[具体人员名单] <a class="header-anchor" href="#参会人员-具体人员名单" aria-label="Permalink to &quot;参会人员：[具体人员名单]&quot;">​</a></h4><h4 id="主要议题" tabindex="-1">主要议题： <a class="header-anchor" href="#主要议题" aria-label="Permalink to &quot;主要议题：&quot;">​</a></h4><ol><li><p><strong>OS 8 构建问题</strong></p><ul><li>上周发送的 OS 8 构建失败，导致 Crimson 构建也未能工作。</li><li>问题根源与去年十月份出现的问题相同，Gluster 集群底层基础设施损坏了部分 VM 磁盘。</li><li>正在进行基础设施从 Gluster 迁移的工作，但尚未完成。</li></ul></li><li><p><strong>Ceph Java 绑定问题</strong></p><ul><li>构建失败的唯一原因是 Ceph JNI 绑定，但这些绑定并不十分重要。</li><li>如果未来24小时内无法修复，计划完全禁用 Ceph 的 Java 相关功能。</li><li>Dan 认为他有一个修复方案，可能已经解决了问题。</li></ul></li><li><p><strong>Crimson 测试更新</strong></p><ul><li>由于构建问题，Crimson 的测试工作受到阻碍。</li><li>正在设置一个四节点的 Twister 集群进行测试。</li><li>目前没有 Crimson 的 Reef 构建镜像，因此使用 Quincy 进行测试。</li><li>正在更新上游跟踪器，并与 Nixon 沟通获取更多信息。</li></ul></li><li><p><strong>Kevin 的加入与工作更新</strong></p><ul><li>Kevin 首次参加 Crimson 会议，希望了解当前开发情况并提供帮助。</li><li>Kevin 正在处理一些 Ceph 64 的 bug 修复。</li></ul></li><li><p><strong>内存泄漏问题</strong></p><ul><li>发现了内存泄漏的根源，与 CPU 核心间的内存管理有关。</li><li>正在测试修复方案，并计划提交给社区。</li></ul></li></ol><h4 id="决定事项" tabindex="-1">决定事项： <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项：&quot;">​</a></h4><ul><li>如果 Ceph Java 绑定在24小时内无法修复，将禁用相关功能。</li><li>继续进行 Crimson 的测试和文档工作。</li><li>解决内存泄漏问题，并提交修复方案给社区。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划： <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划：&quot;">​</a></h4><ul><li>继续监控和解决 OS 8 构建问题。</li><li>完成 Crimson 的测试和文档工作。</li><li>测试并提交内存泄漏的修复方案。</li></ul><h4 id="其他事项" tabindex="-1">其他事项： <a class="header-anchor" href="#其他事项" aria-label="Permalink to &quot;其他事项：&quot;">​</a></h4><ul><li>会议结束时，希望在接下来的24小时内解决构建问题。</li></ul><h4 id="会议总结" tabindex="-1">会议总结： <a class="header-anchor" href="#会议总结" aria-label="Permalink to &quot;会议总结：&quot;">​</a></h4><p>会议讨论了多个技术问题，包括 OS 8 构建失败、Ceph Java 绑定问题、Crimson 测试更新以及内存泄漏问题。团队成员正在积极寻找解决方案，并计划在短期内完成相关工作。希望在接下来的24小时内解决构建问题，以便继续推进其他工作。</p><h4 id="会议记录人-记录人姓名" tabindex="-1">会议记录人：[记录人姓名] <a class="header-anchor" href="#会议记录人-记录人姓名" aria-label="Permalink to &quot;会议记录人：[记录人姓名]&quot;">​</a></h4><h4 id="会议结束时间-具体时间" tabindex="-1">会议结束时间：[具体时间] <a class="header-anchor" href="#会议结束时间-具体时间" aria-label="Permalink to &quot;会议结束时间：[具体时间]&quot;">​</a></h4>',15)])])}const c=e(r,[["render",o]]);export{_ as __pageData,c as default};
